verus! {
    fn is_smaller(arr1: &Vec<i32>, arr2: &Vec<i32>) -> (result: bool)
        requires
            arr1.len() == arr2.len(), // Ensure both arrays have the same length
        ensures
            result == (forall|i: nat| (i < arr1.len() as nat) ==> (arr1[i as usize] > arr2[i as usize])) // Postcondition: result is true if arr1[i] > arr2[i] for all valid i
    {
        let mut idx: usize = 0;
        let mut all_greater: bool = true; // Initialize result to true

        while idx < arr1.len()
            invariant
                idx <= arr1.len(),
                all_greater ==> (forall|j: nat| (j < idx as nat) ==> (arr1[j as usize] > arr2[j as usize])), // Invariant to maintain the condition for all previous indices
            decreases arr1.len() - idx,
        {
            if arr1[idx] <= arr2[idx] {
                all_greater = false; // If any element is not greater, set result to false
            }
            idx = idx + 1; // Move to the next index
        }

        all_greater // Return the result
    }
}

